    if ( options === void 0 ) options = {};

    var gap = options.gap; if ( gap === void 0 ) gap = defaultLine.gap;
    var width = options.width; if ( width === void 0 ) width = defaultLine.width;
    var color = options.color; if ( color === void 0 ) color = defaultColor;
